import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outpadD, int outpadH, int outpadW,
    int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <ATen/cuda/CUDAContext.h>
#include <cute/tensor.hpp>
#include <type_traits>
using namespace cute;
constexpr int WTILE = 4;
template <typename T, int COTILE>
__global__ void convtranspose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int KD, int KH, int KW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int groups,
    int Dout, int Hout, int Wout)
{
    extern __shared__ unsigned char smem_raw[];
    const int tid = threadIdx.x;
    const int Threads = blockDim.x;
    int64_t nz = blockIdx.z;
    int out_per_group = Cout / groups;
    int in_per_group  = Cin / groups;
    int num_tiles_per_batch = Cout / COTILE;
    int n = (int)(nz / num_tiles_per_batch);
    int tile_idx = (int)(nz % num_tiles_per_batch);
    int co_base = tile_idx * COTILE;
    int g = co_base / out_per_group;
    int co_local_base = co_base - g * out_per_group;
    int ci_base = g * in_per_group;
    int K = KD * KH * KW;
    int weight_count = in_per_group * K;
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    T* sX_ptr = sW_ptr + weight_count * COTILE;   // cache of one (id, ih) input row: [in_per_group][Win]
    // Load weight slice for COTILE output channels into shared memory
    // Global weight layout: [Cin, out_per_group, KD, KH, KW]
    for (int idx = tid; idx < weight_count * COTILE; idx += Threads) {
        int t = idx / weight_count;
        int wrem = idx - t * weight_count;
        int ci_local = wrem / K;
        int krem = wrem % K;
        int ci_global = ci_base + ci_local;
        int co_local = co_local_base + t;
        int64_t widx = ((int64_t)ci_global * out_per_group + co_local) * K + krem;
        sW_ptr[idx] = W[widx];
    }
    __syncthreads();
    auto sW = make_tensor(make_smem_ptr(sW_ptr),
                           make_shape(COTILE, in_per_group, KD, KH, KW),
                           make_stride(weight_count, K, KH * KW, KW, 1));
    int64_t sXn = (int64_t)Cin * Din * Hin * Win;
    int64_t sXc = (int64_t)Din * Hin * Win;
    int64_t sXd = (int64_t)Hin * Win;
    int64_t sXh = Win;
    auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                           make_shape(Cin, Din, Hin, Win),
                           make_stride(sXc, sXd, sXh, Int<1>{}));
    int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
    int64_t sYc = (int64_t)Dout * Hout * Wout;
    int64_t sYd = (int64_t)Hout * Wout;
    int64_t sYh = Wout;
    auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                           make_shape(Cout, Dout, Hout, Wout),
                           make_stride(sYc, sYd, sYh, Int<1>{}));
    // Decode a tile of (od,oh) rows per block; blockIdx.x tiles Wout using
    // per-thread register blocking (WTILE) to reuse cached weights across
    // multiple output columns and reduce shared-memory traffic.
    constexpr int ROWTILE = 4;
    int ow0 = blockIdx.x * (Threads * WTILE) + tid;
    int ow[WTILE];
    bool valid_ow[WTILE];
    #pragma unroll
    for (int j = 0; j < WTILE; ++j) {
        ow[j] = ow0 + j * Threads;
        valid_ow[j] = (ow[j] < Wout);
    }
    float bias_val[COTILE];
    #pragma unroll
    for (int t = 0; t < COTILE; ++t) {
        bias_val[t] = (Bias != nullptr) ? (float)Bias[co_base + t] : 0.0f;
    }
    int64_t total_rows = (int64_t)Dout * Hout;
    for (int r = 0; r < ROWTILE; ++r) {
        int64_t nyz = (int64_t)blockIdx.y * ROWTILE + r;
        if (nyz >= total_rows) break;
        int od = (int)(nyz / Hout);
        int oh = (int)(nyz % Hout);
        float acc[WTILE][COTILE];
        #pragma unroll
        for (int j = 0; j < WTILE; ++j) {
            #pragma unroll
            for (int t = 0; t < COTILE; ++t) acc[j][t] = bias_val[t];
        }
        for (int kd = 0; kd < KD; ++kd) {
            int id_num = od + padD - kd;
            bool id_valid = (id_num >= 0) && (id_num % strideD == 0);
            int id = id_valid ? (id_num / strideD) : -1;
            if (id_valid && id >= Din) id_valid = false;
            for (int kh = 0; kh < KH; ++kh) {
                int ih_num = oh + padH - kh;
                bool ih_valid = (ih_num >= 0) && (ih_num % strideH == 0);
                int ih = ih_valid ? (ih_num / strideH) : -1;
                if (ih_valid && ih >= Hin) ih_valid = false;
                if (!id_valid || !ih_valid) continue;
                // Cooperatively stage the input row for (id, ih) across all ci_local, iw
                // Reused across all COTILE output channels in this block, and across
                // the ROWTILE output rows handled by this CTA
                for (int idx = tid; idx < in_per_group * Win; idx += Threads) {
                    int ci_local = idx / Win;
                    int iw_ = idx - ci_local * Win;
                    int ci_global = ci_base + ci_local;
                    sX_ptr[idx] = mX(ci_global, id, ih, iw_);
                }
                __syncthreads();
                for (int kw = 0; kw < KW; ++kw) {
                    int iw_val[WTILE];
                    bool iw_ok[WTILE];
                    bool any_valid = false;
                    #pragma unroll
                    for (int j = 0; j < WTILE; ++j) {
                        iw_ok[j] = false;
                        if (!valid_ow[j]) continue;
                        int iw_num = ow[j] + padW - kw;
                        if (iw_num < 0) continue;
                        if (iw_num % strideW != 0) continue;
                        int iwv = iw_num / strideW;
                        if (iwv >= Win) continue;
                        iw_val[j] = iwv;
                        iw_ok[j] = true;
                        any_valid = true;
                    }
                    if (!any_valid) continue;
                    #pragma unroll 4
                    for (int ci_local = 0; ci_local < in_per_group; ++ci_local) {
                        float xval[WTILE];
                        #pragma unroll
                        for (int j = 0; j < WTILE; ++j) {
                            xval[j] = iw_ok[j] ? (float)sX_ptr[ci_local * Win + iw_val[j]] : 0.0f;
                        }
                        #pragma unroll
                        for (int t = 0; t < COTILE; ++t) {
                            float wval = (float)sW(t, ci_local, kd, kh, kw);
                            #pragma unroll
                            for (int j = 0; j < WTILE; ++j) {
                                acc[j][t] += xval[j] * wval;
                            }
                        }
                    }
                }
                __syncthreads();
            }
        }
        #pragma unroll
        for (int j = 0; j < WTILE; ++j) {
            if (!valid_ow[j]) continue;
            #pragma unroll
            for (int t = 0; t < COTILE; ++t) {
                mY(co_base + t, od, oh, ow[j]) = (T)acc[j][t];
            }
        }
    }
}
torch::Tensor convtranspose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outpadD, int outpadH, int outpadW,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(w.is_cuda(), "w must be CUDA");
    if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
    if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
    TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, KD, KH, KW]");
    auto x_c = x.contiguous();
    auto w_c = w.contiguous();
    int64_t N   = x_c.size(0);
    int64_t Cin = x_c.size(1);
    int64_t Din = x_c.size(2);
    int64_t Hin = x_c.size(3);
    int64_t Win = x_c.size(4);
    int64_t out_per_group = w_c.size(1);
    int64_t KD = w_c.size(2);
    int64_t KH = w_c.size(3);
    int64_t KW = w_c.size(4);
    int64_t Cout = out_per_group * groups;
    TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    int64_t Dout = (Din - 1) * strideD - 2 * padD + KD + outpadD;
    int64_t Hout = (Hin - 1) * strideH - 2 * padH + KH + outpadH;
    int64_t Wout = (Win - 1) * strideW - 2 * padW + KW + outpadW;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (b.has_value()) {
        b_c = b.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }
    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
    // Choose a compile-time channel tile (register blocking) that evenly divides
    // out_per_group so that no tile crosses a group boundary. This lets a single
    // block reuse the staged input row across multiple output channels, cutting
    // redundant global-memory traffic for the activation reload. The tile size must
    // also respect the device's actual shared-memory budget.
    int device_id = x.get_device();
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
    // Leave a little headroom for driver bookkeeping.
    size_t smem_budget = (max_smem_optin > 1024) ? (size_t)(max_smem_optin - 1024) : (size_t)max_smem_optin;
    int64_t in_per_group0 = Cin / groups;
    size_t per_channel_weight_bytes = (size_t)in_per_group0 * KD * KH * KW * sizeof(float);
    size_t input_row_bytes = (size_t)in_per_group0 * Win * sizeof(float);
    int COTILE = 1;
    {
        int candidates[4] = {8, 4, 2, 1};
        bool found = false;
        for (int i = 0; i < 4; ++i) {
            int cand = candidates[i];
            if (out_per_group % cand != 0) continue;
            size_t needed = per_channel_weight_bytes * (size_t)cand + input_row_bytes;
            if (needed <= smem_budget) {
                COTILE = cand;
                found = true;
                break;
            }
        }
        if (!found) COTILE = 1;
    }
    constexpr int Threads = 128;
    constexpr int ROWTILE = 4;
    dim3 block(Threads);
    int64_t num_tiles_per_batch = Cout / COTILE;
    int64_t row_tiles = (Dout * Hout + ROWTILE - 1) / ROWTILE;
    dim3 grid(
        (unsigned)((Wout + Threads * WTILE - 1) / (Threads * WTILE)),
        (unsigned)row_tiles,
        (unsigned)(N * num_tiles_per_batch)
    );
    size_t smem_bytes = per_channel_weight_bytes * (size_t)COTILE + input_row_bytes;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(device_id).stream();
    auto launch = [&](auto cotile_const) {
        constexpr int CT = decltype(cotile_const)::value;
        auto attr_err = cudaFuncSetAttribute(
            convtranspose3d_kernel<float, CT>,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            (int)smem_bytes
        );
        TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
        convtranspose3d_kernel<float, CT><<<grid, block, smem_bytes, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,
            (int)Cout, (int)KD, (int)KH, (int)KW,
            strideD, strideH, strideW,
            padD, padH, padW,
            groups,
            (int)Dout, (int)Hout, (int)Wout
        );
    };
    if (COTILE == 8) {
        launch(std::integral_constant<int, 8>{});
    } else if (COTILE == 4) {
        launch(std::integral_constant<int, 4>{});
    } else if (COTILE == 2) {
        launch(std::integral_constant<int, 2>{});
    } else {
        launch(std::integral_constant<int, 1>{});
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

convtranspose3d_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["convtranspose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a custom CUDA kernel using CuTe
    tensors for indexing, with shared-memory weight caching per output channel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.output_padding = tuple(output_padding)
        self.groups = groups

        # Use a reference ConvTranspose3d purely to obtain correctly-initialized
        # parameters with the exact same shapes/initialization scheme as PyTorch.
        ref = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                  stride=stride, padding=padding,
                                  output_padding=output_padding, groups=groups, bias=bias)
        self.weight = nn.Parameter(ref.weight.data.clone())
        if bias:
            self.bias = nn.Parameter(ref.bias.data.clone())
        else:
            self.register_parameter("bias", None)

        self._ext = convtranspose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.convtranspose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups,
        )

